/* ============================================================
   MISSION HERO — mission-hero.module.css
   Matches: .mission-page-banner on our-mission.html
   ============================================================ */

.section {
  background-color: #0000;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

.inner {
  text-align: center;
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
}

/* ── Badge (.missionsubott) ── */
.badge {
  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  margin-bottom: 17px;
  padding: 0 13px;
  line-height: 14px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 700;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  padding-top: 6px;
  padding-bottom: 6px;
  margin: 0;
}

/* ── Heading (.web-ban-title) ── */
.heading {
  color: var(--color-brand-navy);
  margin-top: 0;
  margin-bottom: 10px;
  padding: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

/* ── Subtitle (.h1-season-seeing.web-h1) ── */
.subtitle {
  color: var(--color-text-secondary);
  max-width: 53rem;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin-bottom: 0;
}

/* ── Stat badges wrapper (.web-job-attention) ── */
.badgeGridWrap {
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
}

/* ── Badges row (.web-ban-grid.mob-2grid) ── */
.badgeGrid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex: 0 auto;
  width: auto;
  display: flex;
}

/* ── Individual badge (.web-grid-box) ── */
.statBadge {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  width: auto;
  padding: 15px;
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: flex;
  box-shadow: var(--shadow-card);
}

.statIcon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}

.statLabel {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  margin: 0;
  text-align: left;
}

/* ── CTA buttons ── */
.ctaRow {
  justify-content: center;
  align-items: center;
  margin-top: 1.5rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
}

/* First button: Book a Demo (.navy-arrow-btn.margin-left-0) */
