  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 25px;
  font-weight: 700;
  line-height: 1.35;
  text-transform: capitalize;
}

.contentPara {
  color: rgba(255, 255, 255, 0.8);
  text-align: left;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin: 0;
}

/* ============================================================
   min-width: 1280px
