    grid-row-gap: 15px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    width: 100%;
  }

  .statBadge {
    width: 100%;
    padding-left: 20px;
    padding-right: 20px;
  }

  .contentGrid {
    grid-template-columns: 1fr;
  }
