/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .heading {
    font-size: 2rem;
    line-height: 1.25;
  }

  .contentCol {
    padding: 30px;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
